DOCS=ROOT/'docs/plans/isc2-cc-2026'
def load(name):return json.loads((OUT/name).read_text(encoding='utf-8'))
def save(name,data):(OUT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
