changes=[]
allowed=[(303,310),(320,351),(1278,1278),(1298,1298),(1336,1336),(1339,1339),(1497,1497)]
for name in ['domain-5.md','domain-5-scenarios.js']:
    old=(OUT/('before-'+name)).read_text(encoding='utf-8').splitlines()
    new=(ROOT/'content/isc2-cc-2026/reading'/name).read_text(encoding='utf-8').splitlines()
    for tag,a,b,c,d in difflib.SequenceMatcher(None,old,new,autojunk=False).get_opcodes():
        if tag=='equal':continue
        if name.endswith('.md'):assert any(lo<=a+1 and b<=hi for lo,hi in allowed),(a,b,'unrelated Markdown edit')
        else:assert a+1 in [8,47,50] and b==a+1,(a,b,'unrelated JavaScript edit')
        changes.append({'path':'content/isc2-cc-2026/reading/'+name,'beforeStartLine':a+1,'beforeEndLine':b,'afterStartLine':c+1,'afterEndLine':d,'original':'\n'.join(old[a:b]),'replacement':'\n'.join(new[c:d]),'finding':'ACC-D5-01' if name.endswith('.md') and a+1 in [303,309,1298,1497] else 'ACC-D5-02'})
save('exact-changes.json',changes)
